window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[274]={"id":"274","numero":274,"titre":"Vomissements","objectifs":[{"id":"274-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique en cas de vomissements chez l’enfant","contenu":"<p>Devant des <span class=\"kw-clinique\">vomissements</span> de l'enfant, la démarche vise d'abord à <strong>écarter <span class=\"kw-clinique\">les</span> urgences</strong> — chirurgicales, neurologiques et métaboliques — avant de retenir une cause banale. Elle repose sur une <span class=\"kw-clinique\">anamnèse</span> et un <span class=\"kw-clinique\">examen clinique</span> orientés, sans examen complémentaire systématique.</p>\n\n      <h4 style=\"margin:16px 0 8px;font-size:15px;font-weight:700;\">Étape 1 — Caractériser le <span class=\"kw-clinique\">vomissement</span></h4>\n      <p>Distinguer <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">vomissements aigus ou occasionnels</span> des <span class=\"kw-def\">vomissements chroniques ou récurrents</span> : ce premier tri conditionne tout le raisonnement étiologique. Préciser l'<span class=\"kw-clinique\">horaire</span>, le <span class=\"kw-clinique\">caractère bilieux ou non</span>, l'<span class=\"kw-clinique\">aspect</span> (en jet, lait caillé) et le <span class=\"kw-clinique\">retentissement pondéral</span>.</p>\n\n      <h4 style=\"margin:16px 0 8px;font-size:15px;font-weight:700;\">Étape 2 — Devant des <span class=\"kw-clinique\">vomissements</span> chroniques, éliminer <span class=\"kw-clinique\">les</span> erreurs diététiques</h4>\n      <p>L'<span class=\"kw-clinique\">interrogatoire alimentaire</span> recherche en premier lieu un <span class=\"kw-etio\">forcing alimentaire</span> et des <span class=\"kw-etio\">quantités excessives</span> : cause banale et fréquente, à écarter avant tout bilan.</p>\n\n      <h4 style=\"margin:16px 0 8px;font-size:15px;font-weight:700;\">Étape 3 — Rechercher un <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">infectieux</span></span></h4>\n      <p>La présence d'un <span class=\"kw-clinique\">syndrome infectieux</span> oriente d'emblée vers une <span class=\"kw-etio\">gastroentérite</span>, une <span class=\"kw-etio\">infection ORL</span> ou une infection plus profonde (<span class=\"kw-etio\">PNA</span>, <span class=\"kw-alerte\">méningite</span>, <span class=\"kw-etio\">appendicite</span>).</p>\n\n      <h4 style=\"margin:16px 0 8px;font-size:15px;font-weight:700;\">Étape 4 — Traquer systématiquement <span class=\"kw-clinique\">les</span> urgences</h4>\n      <p>C'est le temps fort de la démarche : aucune de ces situations ne doit être méconnue.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-alerte\">Urgence</span> à éliminer</th><th><span class=\"kw-def\">Terrain</span> / signe d'appel</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Sténose du pylore</span></td><td>Jeune nourrisson, intervalle libre de <span class=\"kw-chiffre\">3-5 semaines</span>, <span class=\"kw-clinique\">vomissements</span> en jet non bilieux, cassure pondérale</td></tr>\n          <tr><td><span class=\"kw-alerte\">Occlusion · volvulus · IIA</span></td><td><span class=\"kw-clinique\">Vomissements</span> bilieux, douleurs abdominales, météorisme — <span class=\"kw-alerte\">urgence</span> chirurgicale</td></tr>\n          <tr><td><span class=\"kw-alerte\">HTIC</span></td><td><span class=\"kw-clinique\">Vomissements</span> en jet matinaux, céphalées — tumeur cérébrale, hématome sous-dural ou extradural</td></tr>\n          <tr><td><span class=\"kw-alerte\">Cause métabolique</span></td><td><span class=\"kw-bio\">Hypoglycémie</span>, <span class=\"kw-alerte\">acidocétose diabétique</span> inaugurale</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">📌 <strong>Signe d'alarme :</strong> le <span class=\"kw-clinique\">caractère bilieux</span> d'un <span class=\"kw-clinique\">vomissement</span> chez le nourrisson est un <span class=\"kw-alerte\">drapeau rouge</span> chirurgical — il impose d'éliminer une obstruction sur le cadre duodénal ou un <span class=\"kw-alerte\">volvulus sur malrotation</span>.</div>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>Trou de fiche source.</strong> L'<strong>algorithme décisionnel précis du Collège de pédiatrie</strong> n'est pas détaillé dans la fiche source, qui y renvoie sans le reproduire. La démarche ci-dessus reconstitue <span class=\"kw-clinique\">les</span> étapes à partir des seuls éléments présents dans la fiche ; l'arbre formalisé reste à compléter par Kevin (Collège de pédiatrie).</div>","frequence":1},{"id":"274-2","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales causes de vomissements à connaître chez l’enfant","contenu":"<p>Chez l'enfant, l'orientation étiologique repose d'abord sur la distinction <span class=\"kw-def\">aigus / occasionnels</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-def\">chroniques / récurrents</span>, puis sur la présence ou non d'un <span class=\"kw-clinique\">syndrome infectieux</span>.</p>\n\n      <h4 style=\"margin:16px 0 8px;font-size:15px;font-weight:700;\"><span class=\"kw-clinique\">Vomissements</span> aigus ou occasionnels</h4>\n      <table >\n        <thead><tr><th>Contexte</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Avec syndrome infectieux</span></td><td>\n            <ul>\n              <li><span class=\"kw-etio\">Gastroentérite</span> ++ — <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">vomissements</span> peuvent précéder la diarrhée de plusieurs heures</li>\n              <li><span class=\"kw-etio\">Infections ORL</span> ++ — otite, rhinopharyngite, angine, stomatite</li>\n              <li>Autres : <span class=\"kw-etio\">PNA</span>, <span class=\"kw-alerte\">méningite</span>, <span class=\"kw-etio\">appendicite</span>, <span class=\"kw-alerte\">péritonite</span>, <span class=\"kw-etio\">hépatite</span>, infection respiratoire (<span class=\"kw-etio\">coqueluche émétisante</span>)</li>\n            </ul></td></tr>\n          <tr><td><span class=\"kw-clinique\">Sans syndrome infectieux — nouveau-né</span></td><td>\n            <ul>\n              <li><span class=\"kw-alerte\">ECUN</span> (prématuré)</li>\n              <li><span class=\"kw-alerte\">Atrésie duodéno-jéjunale</span></li>\n              <li><span class=\"kw-etio\">Maladie de Hirschsprung</span></li>\n              <li><span class=\"kw-alerte\">Iléus méconial</span></li>\n              <li><span class=\"kw-alerte\">Volvulus sur malrotation intestinale</span></li>\n            </ul></td></tr>\n          <tr><td><span class=\"kw-clinique\">Sans syndrome infectieux — nourrisson / enfant</span></td><td>\n            <ul>\n              <li><strong>Chirurgical :</strong> <span class=\"kw-alerte\">hernie inguinale étranglée</span>, <span class=\"kw-alerte\">volvulus</span>, <span class=\"kw-alerte\">occlusion sur bride</span>, <span class=\"kw-alerte\">invagination intestinale aiguë (IIA)</span>, <span class=\"kw-etio\">appendicite</span>, <span class=\"kw-alerte\">torsion du cordon spermatique ou d'annexe</span></li>\n              <li><strong>Neurologique :</strong> <span class=\"kw-alerte\">HTIC</span> — hématome sous-dural ou extradural, <span class=\"kw-etio\">tumeur cérébrale</span></li>\n              <li><strong>Métabolique / <span class=\"kw-etio\">toxique</span> :</strong> <span class=\"kw-bio\">hypoglycémie</span>, <span class=\"kw-alerte\">acidocétose diabétique</span>, intoxication médicamenteuse ou au <span class=\"kw-etio\">CO</span>, <span class=\"kw-etio\">hypervitaminoses A et D</span></li>\n              <li><strong><span class=\"kw-etio\">Allergique</span> :</strong> allergies alimentaires (forme <span class=\"kw-chiffre\">IgE</span>-médiée, <span class=\"kw-etio\">SEIPA</span> aigu)</li>\n            </ul></td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:16px 0 8px;font-size:15px;font-weight:700;\"><span class=\"kw-clinique\">Vomissements</span> chroniques ou récurrents</h4>\n      <div class=\"callout callout-info\">📌 Devant des <span class=\"kw-clinique\">vomissements</span> chroniques de l'enfant, <strong>éliminer en premier lieu <span class=\"kw-clinique\">les</span> erreurs diététiques</strong> à l'interrogatoire : <span class=\"kw-etio\">quantités excessives</span>, <span class=\"kw-etio\">forcing alimentaire</span>.</div>\n      <table >\n        <thead><tr><th>Origine</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Digestive</span></td><td>\n            <ul>\n              <li><span class=\"kw-alerte\">Sténose du pylore</span> — <span class=\"kw-alerte\">urgence</span> du jeune nourrisson (voir focus ci-dessous)</li>\n              <li><span class=\"kw-etio\">RGO</span></li>\n              <li><span class=\"kw-etio\">APLV</span> — forme retardée, SEIPA chronique</li>\n              <li><span class=\"kw-etio\">Maladie cœliaque</span> — cause rare de <span class=\"kw-clinique\">vomissements</span></li>\n            </ul></td></tr>\n          <tr><td><span class=\"kw-clinique\">Extra-digestive</span></td><td>\n            <ul>\n              <li><span class=\"kw-alerte\">HTIC</span>, <span class=\"kw-etio\">insuffisance cardiaque</span>, <span class=\"kw-etio\">tubulopathies</span>, <span class=\"kw-etio\">hépatopathies</span>, <span class=\"kw-ttt\">chimiothérapies anticancéreuses</span></li>\n              <li><span class=\"kw-alerte\">Acidocétose diabétique</span>, <span class=\"kw-etio\">hyperplasie congénitale des surrénales</span></li>\n              <li>Maladies métaboliques héréditaires : <span class=\"kw-etio\">galactosémie</span>, <span class=\"kw-etio\">fructosémie</span>, <span class=\"kw-etio\">anomalies du cycle de l'urée</span></li>\n              <li><span class=\"kw-etio\">Vomissements cycliques</span> — épisodes intenses de quelques heures à jours, espacés de plusieurs semaines, sans symptôme associé</li>\n              <li><span class=\"kw-etio\">Vomissements psychogènes</span> — l'une des principales causes de <span class=\"kw-clinique\">vomissements</span> inexpliqués chez l'enfant</li>\n            </ul></td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:18px 0 8px;font-size:15px;font-weight:700;\">Focus — Sténose hypertrophique du pylore</h4>\n      <p>La <span class=\"kw-etio\">sténose hypertrophique du pylore</span> est une <span class=\"kw-alerte\">urgence diagnostique et thérapeutique</span> : hypertrophie des fibres musculaires du pylore réalisant un obstacle progressif à la vidange gastrique.</p>\n      <table >\n        <thead><tr><th>Item</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Terrain</span></td><td>Jeune nourrisson — survenue avec un <span class=\"kw-chiffre\">intervalle libre de 3 à 5 semaines</span> après la naissance ; <span class=\"kw-clinique\">prédominance masculine</span> ; ATCD familiaux parfois présents</td></tr>\n          <tr><td>Installation</td><td>Symptomatologie d'aggravation <strong>progressive</strong></td></tr>\n          <tr><td><span class=\"kw-clinique\">Vomissements</span></td><td><span class=\"kw-clinique\">À distance du repas</span> (<span class=\"kw-chiffre\">30 à 60 min</span>), abondants, <span class=\"kw-clinique\">explosifs en jet</span> sans <span class=\"kw-clinique\">nausée</span>, faits de <span class=\"kw-clinique\">lait caillé blanc non teinté de bile</span></td></tr>\n          <tr><td>Signes associés</td><td><span class=\"kw-alerte\">Cassure de la courbe de poids</span> contrastant avec un <span class=\"kw-clinique\">appétit conservé</span></td></tr>\n          <tr><td>Examen physique</td><td><span class=\"kw-alerte\">Dénutrition</span> et <span class=\"kw-clinique\">déshydratation</span> variables ; palpation d'une <span class=\"kw-clinique\">olive pylorique</span> et ondulations péristaltiques gastriques visibles</td></tr>\n          <tr><td>Paraclinique</td><td><span class=\"kw-bio\">Gaz du sang : alcalose métabolique hypochlorémique</span> ; <span class=\"kw-imagerie\">échographie abdominale</span> (confirmation) : aspect en « cocarde », <span class=\"kw-radio\">épaississement du muscle ≥ 4 mm</span>, allongement du canal pylorique, stase gastrique</td></tr>\n          <tr><td>Traitement</td><td><span class=\"kw-alerte\">Urgence</span> symptomatique : correction de la <span class=\"kw-clinique\">déshydratation</span> et des troubles ioniques ; traitement étiologique chirurgical : <span class=\"kw-ttt\">pyloromyotomie longitudinale extramuqueuse</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">⚠️ Le caractère <strong>non bilieux</strong> (lait caillé blanc) des <span class=\"kw-clinique\">vomissements</span> de la sténose du pylore est un signe clé : un vomissement <span class=\"kw-clinique\">bilieux</span> oriente au contraire vers une obstruction en aval du pylore.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 286 — <span class=\"kw-clinique\">Diarrhée</span> aiguë - <span class=\"kw-clinique\">déshydratation</span> · 354 — Syndrome occlusif · 356 — <span class=\"kw-clinique\">Appendicite</span> · 299 — Tumeur intracranienne · 271 — <span class=\"kw-clinique\">RGO</span> - hernie hiatale</em></p>","frequence":0},{"id":"274-3","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens complémentaires en cas de vomissements évoquant une cause secondaire (tumeur cérébrale, cause chirurgicale, intoxication)","contenu":"<p>Aucun examen n'est réalisé de façon systématique. <span class=\"kw-clinique\">Les</span> explorations se justifient soit pour <strong>évaluer le retentissement</strong> de <span class=\"kw-clinique\">vomissements</span> prolongés ou compliqués, soit pour <strong>documenter une étiologie secondaire</strong> suspectée — en particulier les causes de l'intitulé : <span class=\"kw-etio\">tumeur cérébrale</span>, <span class=\"kw-alerte\">cause chirurgicale</span>, <span class=\"kw-etio\">intoxication</span>.</p>\n\n      <h4 style=\"margin:16px 0 8px;font-size:15px;font-weight:700;\">Bilan de retentissement</h4>\n      <p><strong>Indications :</strong> <span class=\"kw-clinique\">vomissements</span> <span class=\"kw-def\">chroniques</span> (<span class=\"kw-chiffre\">datant de plus de 7 jours</span>) ou <span class=\"kw-clinique\">vomissement</span> aigu suspect de complication — patient vulnérable, <span class=\"kw-clinique\">déshydratation</span>, <span class=\"kw-clinique\">amaigrissement</span>, <span class=\"kw-clinique\">AEG</span>.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Recherche</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">NFS</span></td><td>Hémoconcentration (<span class=\"kw-bio\">hématocrite</span>)</td></tr>\n          <tr><td><span class=\"kw-bio\">Ionogramme sanguin</span></td><td><span class=\"kw-bio\">Alcalose métabolique</span>, <span class=\"kw-bio\">hypochlorémie</span>, <span class=\"kw-bio\">hypokaliémie</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Urée, créatinine, ionogramme urinaire</span></td><td><span class=\"kw-ci\">Insuffisance rénale</span> fonctionnelle</td></tr>\n          <tr><td><span class=\"kw-bio\">Albuminémie, pré-albuminémie</span></td><td>Dénutrition</td></tr>\n          <tr><td><span class=\"kw-bio\">Bilan d'hémostase</span></td><td>En cas d'hémorragie digestive associée</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:16px 0 8px;font-size:15px;font-weight:700;\">Bilan étiologique</h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">β-hCG</span></td><td>Femme en âge de procréer avec <span class=\"kw-clinique\">vomissements</span> récents</td></tr>\n          <tr><td><span class=\"kw-bio\">Glycémie, bandelette urinaire</span></td><td>Patient diabétique — recherche d'<span class=\"kw-alerte\">acidocétose</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Calcémie corrigée ou ionisée</span></td><td>Patient avec métastases osseuses (hypercalcémie)</td></tr>\n          <tr><td><span class=\"kw-imagerie\">EOGD</span></td><td><span class=\"kw-clinique\">Vomissements</span> post-prandiaux avec <span class=\"kw-clinique\">AEG</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">TDM abdomino-pelvienne</span></td><td><strong>Cause chirurgicale</strong> — syndrome occlusif</td></tr>\n          <tr><td><span class=\"kw-imagerie\">TDM cérébrale</span></td><td><strong>Cause <span class=\"kw-etio\">tumorale</span></strong> — <span class=\"kw-clinique\">vomissement</span> en jet, céphalée matinale, signes neurologiques</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Scintigraphie de vidange gastrique</span></td><td>Recherche de gastroparésie : <span class=\"kw-clinique\">vomissements</span> chroniques avec <span class=\"kw-etio\">diabète</span> ancien, <span class=\"kw-clinique\">sclérodermie</span>, ou vagotomie accidentelle post-opératoire</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Ponction lombaire</span></td><td><span class=\"kw-clinique\">Syndrome méningé</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">ECG</span></td><td>Recherche d'<span class=\"kw-alerte\">IDM</span> inférieur — typiquement chez le diabétique</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">📌 <strong>Aucun examen complémentaire n'est systématique.</strong> Le choix est entièrement guidé par l'orientation clinique. Le mapping de l'intitulé : <span class=\"kw-etio\">tumeur cérébrale</span> → <span class=\"kw-imagerie\">TDM cérébrale</span> ; <span class=\"kw-alerte\">cause chirurgicale</span> → <span class=\"kw-imagerie\">TDM abdomino-pelvienne</span> ; <span class=\"kw-etio\">intoxication</span> → recherche <span class=\"kw-ttt\">biologique</span> orientée (<span class=\"kw-bio\">glycémie</span> / bandelette pour l'acidocétose, dosages toxiques et <span class=\"kw-etio\">médicamenteux</span> selon le toxique suspecté).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 299 — Tumeur intracranienne · 354 — Syndrome occlusif · 100 — <span class=\"kw-clinique\">Céphalée</span></em></p>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/pyloric-stenosis-1","label":"Radiopaedia : Pyloric stenosis 1"}]},{"id":"274-4","rang":"B","rubrique":"Prise en charge","titre":"Connaître le traitement étiologique des vomissements chez l’enfant","contenu":"<p>Le traitement étiologique consiste, par principe, à <strong>traiter la cause</strong> identifiée par la démarche diagnostique : il n'existe pas de traitement étiologique « générique » des <span class=\"kw-clinique\">vomissements</span> de l'enfant, chaque cause appelant sa propre prise en charge.</p>\n\n      <h4 style=\"margin:16px 0 8px;font-size:15px;font-weight:700;\">Le modèle détaillé : la sténose du pylore</h4>\n      <p>Le seul traitement étiologique <strong>pleinement détaillé dans la fiche source</strong> est celui de la <span class=\"kw-etio\">sténose hypertrophique du pylore</span>, qui se déroule en deux temps :</p>\n      <ul>\n        <li><strong>Temps symptomatique préalable</strong> — correction de la <span class=\"kw-clinique\">déshydratation</span> et des <span class=\"kw-bio\">troubles ioniques</span> (<span class=\"kw-bio\">alcalose hypochlorémique</span>) : c'est une <span class=\"kw-alerte\">urgence</span> symptomatique, à régler avant tout geste.</li>\n        <li><strong>Temps étiologique chirurgical</strong> — <span class=\"kw-ttt\">pyloromyotomie longitudinale extramuqueuse</span>.</li>\n      </ul>\n\n      <h4 style=\"margin:16px 0 8px;font-size:15px;font-weight:700;\">Pour <span class=\"kw-clinique\">les</span> autres causes</h4>\n      <p>Le principe reste le traitement de l'étiologie sous-jacente : <strong>arrêt du <span class=\"kw-etio\">toxique</span></strong> en cause devant une intoxication, prise en charge chirurgicale d'une <span class=\"kw-alerte\">urgence digestive</span> (volvulus, IIA, occlusion), prise en charge spécialisée d'une <span class=\"kw-alerte\">HTIC</span> ou d'une <span class=\"kw-alerte\">acidocétose diabétique</span>.</p>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>Trou de fiche source.</strong> Le détail du traitement étiologique pédiatrique <strong>cause par cause</strong> (<span class=\"kw-etio\">RGO</span>, APLV, <span class=\"kw-etio\">maladie cœliaque</span>, causes métaboliques héréditaires…) est <strong>lacunaire dans la fiche source</strong>. Ces protocoles sont à compléter par Kevin à partir du Collège de pédiatrie et des items dédiés.</div>","frequence":0},{"id":"274-5","rang":"B","rubrique":"Prise en charge","titre":"Connaître le traitement symptomatique des vomissements chez l’enfant","contenu":"<p>Chez l'enfant, le traitement symptomatique privilégie d'abord <span class=\"kw-clinique\">les</span> <strong>mesures non médicamenteuses</strong> ; le recours <span class=\"kw-etio\">médicamenteux</span> est limité et strictement encadré.</p>\n\n      <h4 style=\"margin:16px 0 8px;font-size:15px;font-weight:700;\">Traitement <span class=\"kw-etio\">médicamenteux</span></h4>\n      <ul>\n        <li>Seul l'<span class=\"kw-ttt\">ondansétron</span> (<span class=\"kw-ttt\">antagoniste des récepteurs 5-HT3</span>) a clairement démontré son efficacité chez l'enfant.</li>\n        <li>Son <span class=\"kw-def\">AMM</span> est toutefois <strong>restreinte</strong> à deux situations : <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">vomissements postopératoires</span> et les <span class=\"kw-clinique\">vomissements induits par les chimiothérapies cytotoxiques</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><span class=\"kw-ci\">Le métoclopramide est contre-indiqué chez l'enfant</span> — risque de <span class=\"kw-clinique\">syndrome extrapyramidal</span> (<span class=\"kw-clinique\">dystonies</span>, dyskinésies aiguës ou tardives). Il ne doit pas être utilisé dans cette indication.</div>\n\n      <h4 style=\"margin:16px 0 8px;font-size:15px;font-weight:700;\">Mesures non médicamenteuses</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Réhydratation</span> adaptée au degré de retentissement (voie orale fractionnée privilégiée).</li>\n        <li><span class=\"kw-clinique\">Fractionnement des repas</span> — petites quantités répétées, alimentation légère.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">📌 <span class=\"kw-clinique\">Les</span> principes généraux du traitement <span class=\"kw-etio\">médicamenteux</span> (classes, cibles, indications / non-indications) sont détaillés dans l'objectif « <em>Connaître les principes de prise en charge médicamenteuse et non médicamenteuse</em> ».</div>","frequence":0},{"id":"274-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les symptômes orientant la démarche diagnostique (aiguë vs chronique)","contenu":"<h4 style=\"margin:4px 0 8px;font-size:15px;font-weight:700;\">Définitions</h4>\n      <table >\n        <thead><tr><th>Terme</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Vomissement</span></td><td><span class=\"kw-clinique\">Rejet brutal par la bouche du contenu gastrique</span>, par contractions cycliques et synchrones de la musculature abdominale, du diaphragme et des muscles respiratoires</td></tr>\n          <tr><td><span class=\"kw-def\">Haut-le-cœur</span></td><td>Mêmes contractions, mais se faisant <strong>contre une glotte fermée</strong> (pas de rejet)</td></tr>\n          <tr><td><span class=\"kw-def\">Nausée</span></td><td>Sensation subjective désagréable non douloureuse, issue du tractus digestif haut, associée au besoin de vomir ou à la sensation d'un <span class=\"kw-clinique\">vomissement</span> imminent</td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>Signes neurovégétatifs associés</strong> — ils accompagnent fréquemment le <span class=\"kw-clinique\">vomissement</span> :</p>\n      <ul>\n        <li>Activation <span class=\"kw-def\">parasympathique</span> : <span class=\"kw-clinique\">hypersalivation</span>, <span class=\"kw-clinique\">bradycardie</span>.</li>\n        <li>Activation <span class=\"kw-def\">sympathique</span> : <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">sueurs froides</span>, <span class=\"kw-clinique\">pâleur</span> par vasoconstriction cutanée, <span class=\"kw-clinique\">mydriase</span>.</li>\n      </ul>\n\n      <h4 style=\"margin:16px 0 8px;font-size:15px;font-weight:700;\">Diagnostics différentiels (à distinguer)</h4>\n      <ul>\n        <li><span class=\"kw-etio\">Régurgitations</span> — remontées <strong>passives</strong> du contenu gastrique ou œsophagien jusqu'au pharynx, sans effort de <span class=\"kw-clinique\">vomissement</span>.</li>\n        <li><span class=\"kw-etio\">Mérycisme</span> (<span class=\"kw-clinique\">syndrome de rumination</span>) — régurgitation <strong>volontaire</strong> d'aliments ingérés, remâchés puis redéglutis.</li>\n      </ul>\n\n      <h4 style=\"margin:16px 0 8px;font-size:15px;font-weight:700;\">Aigu <span class=\"kw-bio\">vs</span> chronique : le premier tri</h4>\n      <p>L'<span class=\"kw-clinique\">ancienneté</span> oriente d'emblée la démarche : un <span class=\"kw-clinique\">vomissement</span> est dit <span class=\"kw-def\">aigu</span> lorsqu'il <span class=\"kw-chiffre\">date de moins de 7 jours</span>, <span class=\"kw-def\">chronique</span> lorsqu'il <span class=\"kw-chiffre\">dépasse 7 jours</span> ou récidive.</p>\n\n      <h4 style=\"margin:16px 0 8px;font-size:15px;font-weight:700;\">Sémiologie orientant le diagnostic</h4>\n      <table >\n        <thead><tr><th>Sémiologie</th><th>Orientation</th></tr></thead>\n        <tbody>\n          <tr><td>Matinaux, à jeun, liquide peu glaireux, haut-le-cœur (<span class=\"kw-clinique\">pituites</span>)</td><td><span class=\"kw-etio\">Grossesse</span>, consommation excessive d'<span class=\"kw-etio\">alcool</span>, intoxication, <span class=\"kw-ci\">intolérance</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Matinaux, en jet</span>, sans <span class=\"kw-clinique\">nausée</span> ni haut-le-cœur</td><td><span class=\"kw-alerte\">HTIC</span></td></tr>\n          <tr><td>Post-prandiaux tardifs répétés, aliments nauséabonds partiellement digérés</td><td>Obstruction chronique gastro-duodénale — organique ou fonctionnelle (<span class=\"kw-etio\">gastroparésie</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Fécaloïdes</span></td><td>Obstruction basse (grêle distal, côlon), <span class=\"kw-clinique\">fistule</span> gastro-colique (exceptionnel)</td></tr>\n          <tr><td>Per-prandiaux ou immédiatement après le repas</td><td>Cause <span class=\"kw-etio\">psychogène</span> (fréquente, mais diagnostic d'élimination)</td></tr>\n          <tr><td>Plutôt en fin de journée, alimentaires, précédés de <span class=\"kw-clinique\">nausées</span> / ballonnements / satiété / crampes</td><td><span class=\"kw-alerte\">Syndrome obstructif</span> (obstacle organique incomplet)</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">📌 <strong>Quatre étiologies à toujours évoquer</strong> devant tout <span class=\"kw-clinique\">vomissement</span>, quel qu'en soit le tableau : <span class=\"kw-etio\">grossesse</span>, <span class=\"kw-etio\">médicament / toxique / drogue</span>, <span class=\"kw-alerte\">HTIC</span>, <span class=\"kw-alerte\">cause métabolique</span> (<span class=\"kw-alerte\">insuffisance rénale aiguë</span>, insuffisance surrénalienne).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 354 — Syndrome occlusif · 299 — Tumeur intracranienne</em></p>","frequence":0},{"id":"274-7","rang":"A","rubrique":"Étiologies","titre":"Connaître les causes principales digestives et extradigestives (médicamenteux, métabolique, neurologique, ..)","contenu":"<p>Chez l'adulte, le raisonnement étiologique sépare <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">vomissements</span> <span class=\"kw-def\">aigus</span> (<span class=\"kw-chiffre\">moins de 7 jours</span>) des vomissements <span class=\"kw-def\">chroniques</span> (<span class=\"kw-chiffre\">plus de 7 jours</span> ou récidivants), en croisant causes <strong>digestives</strong> et <strong>extra-digestives</strong>.</p>\n\n      <h4 style=\"margin:16px 0 8px;font-size:15px;font-weight:700;\"><span class=\"kw-clinique\">Vomissements</span> aigus (&lt;<span class=\"kw-chiffre\"> 7 jours</span>)</h4>\n      <table >\n        <thead><tr><th>Origine</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Digestive</span></td><td><span class=\"kw-etio\">Gastroentérite aiguë virale</span> saisonnière et <span class=\"kw-etio\">toxi-infection alimentaire</span> = <strong><span class=\"kw-clinique\">les</span> plus fréquentes</strong> ; <span class=\"kw-etio\">colique hépatique</span>, <span class=\"kw-alerte\">pancréatite aiguë</span>, <span class=\"kw-alerte\">syndrome occlusif</span>, <span class=\"kw-alerte\">infarctus mésentérique</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Métabolique</span></td><td><span class=\"kw-bio\">Hyponatrémie</span>, <span class=\"kw-bio\">hypercalcémie</span>, <span class=\"kw-bio\">hypoglycémie</span>, <span class=\"kw-alerte\">insuffisance rénale aiguë</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Endocrinienne</span></td><td><span class=\"kw-etio\">Hyperthyroïdie</span>, <span class=\"kw-alerte\">insuffisance surrénale aiguë</span>, <span class=\"kw-alerte\">acidocétose diabétique</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Neurologique</span></td><td><span class=\"kw-alerte\">Méningite</span>, <span class=\"kw-alerte\">hémorragie sous-arachnoïdienne</span>, <span class=\"kw-alerte\">HTIC</span>, <span class=\"kw-etio\">migraine</span> avec ou sans aura, <span class=\"kw-clinique\">malaise</span> vagal, syndrome labyrinthique</td></tr>\n          <tr><td><span class=\"kw-clinique\">Toxique</span></td><td><span class=\"kw-etio\">Syndrome cannabinoïde</span>, <span class=\"kw-etio\">alcool</span>, <span class=\"kw-etio\">monoxyde de carbone</span>, solvants, nicotine ; médicaments : <span class=\"kw-ttt\">antibiotiques</span>, <span class=\"kw-ttt\">chimiothérapie</span>, <span class=\"kw-ttt\">opiacés</span>, <span class=\"kw-ttt\">néfopam</span>, <span class=\"kw-ttt\">digitaliques</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Autres</span></td><td><span class=\"kw-etio\">Colique néphrétique</span>, <span class=\"kw-etio\">grossesse</span> (dont <span class=\"kw-alerte\">GEU</span>), torsion de kyste ovarien, <span class=\"kw-alerte\">IDM</span>, glaucome aigu</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:16px 0 8px;font-size:15px;font-weight:700;\"><span class=\"kw-clinique\">Vomissements</span> chroniques (&gt;<span class=\"kw-chiffre\"> 7 jours</span> ou récidivants)</h4>\n      <table >\n        <thead><tr><th>Origine</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Digestive — obstruction</span></td><td>Obstructions mécaniques hautes (gastro-duodéno-grêliques, plus rarement colorectales basses), tumorales ou non : <span class=\"kw-etio\">cancer gastrique, duodénal, du grêle</span>, néoplasies du pancréas, <span class=\"kw-clinique\">pseudokyste</span> pancréatique compressif, sténose sur ulcère bénin, carcinose péritonéale, <span class=\"kw-clinique\">maladie de Crohn</span>, sténose post-anastomotique ou post-radique, sténose sur <span class=\"kw-ttt\">AINS</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Digestive — strangulation</span></td><td>Adhérences, brides, hernies</td></tr>\n          <tr><td><span class=\"kw-clinique\">Digestive — fonctionnelle</span></td><td><span class=\"kw-etio\">Gastroparésie</span> (<span class=\"kw-etio\">diabète</span>, <span class=\"kw-clinique\">sclérodermie</span>, amylose), post-vagotomie, pseudo-obstruction intestinale primitive ou secondaire</td></tr>\n          <tr><td><span class=\"kw-clinique\">Psychiatrique</span></td><td><span class=\"kw-clinique\">Anorexie</span> mentale, boulimie, <span class=\"kw-etio\">vomissements psychogènes</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Neurologique</span></td><td><span class=\"kw-alerte\">HTIC</span>, épilepsie</td></tr>\n          <tr><td><span class=\"kw-clinique\">Autres</span></td><td><span class=\"kw-etio\">Grossesse</span> (1ᵉʳ trimestre), <span class=\"kw-etio\">hyperemesis aux cannabinoïdes</span>, <span class=\"kw-clinique\">vomissements</span> cataméniaux, syndrome des vomissements cycliques idiopathiques, <span class=\"kw-ttt\">chimiothérapies cytotoxiques</span>, autres médicaments (digitaliques, <span class=\"kw-ttt\">opiacés</span>)</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:18px 0 8px;font-size:15px;font-weight:700;\">Complications des <span class=\"kw-clinique\">vomissements</span></h4>\n      <table >\n        <thead><tr><th>Complication</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Troubles hydro-électrolytiques</span></td><td>Perte des sécrétions gastriques (riches en H⁺, Cl⁻, K⁺) → <span class=\"kw-bio\">alcalose métabolique</span>, <span class=\"kw-bio\">hypochlorémie</span>, <span class=\"kw-bio\">hypokaliémie</span>, <span class=\"kw-clinique\">déshydratation</span> et <span class=\"kw-ci\">insuffisance rénale</span> fonctionnelle ; hyponatrémie par SIADH possible</td></tr>\n          <tr><td><span class=\"kw-alerte\">Syndrome de Mallory-Weiss</span></td><td>Déchirure longitudinale de la muqueuse du cardia lors d'efforts de <span class=\"kw-clinique\">vomissements</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Syndrome de Boerhaave</span></td><td><span class=\"kw-alerte\">Rupture</span> de la paroi de l'œsophage — exceptionnel, très grave, <span class=\"kw-alerte\">urgence</span> chirurgicale (<span class=\"kw-alerte\">médiastinite</span>)</td></tr>\n          <tr><td><span class=\"kw-alerte\">Pneumopathie d'inhalation (Mendelson)</span></td><td><span class=\"kw-def\">Terrain</span> à risque : troubles de la conscience ou troubles neurologiques ; peut engager le <span class=\"kw-alerte\">pronostic vital</span> (<span class=\"kw-alerte\">SDRA</span>)</td></tr>\n          <tr><td><span class=\"kw-alerte\">Encéphalopathie de Gayet-Wernicke</span></td><td><span class=\"kw-clinique\">Vomissements</span> répétés de la femme enceinte → dénutrition et <span class=\"kw-bio\">carence en vitamine B1</span></td></tr>\n        </tbody>\n      </table>\n      <p style=\"font-size:13px;color:#64748b;margin:6px 0 0;\">Autres complications : hémorragie sous-conjonctivale, perte de l'émail dentaire et caries, hypertrophie parotidienne, hyperamylasémie, œsophagite, cancérisation de l'œsophage (sur <span class=\"kw-clinique\">vomissements</span> chroniques), dénutrition, fracture de côtes, interruption des traitements oraux.</p>\n\n      <h4 style=\"margin:18px 0 8px;font-size:15px;font-weight:700;\">Focus — Mallory-Weiss <span class=\"kw-bio\">vs</span> Boerhaave (à distinguer)</h4>\n      <table >\n        <thead><tr><th></th><th>Mallory-Weiss</th><th>Boerhaave</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Lésion</span></td><td>Déchirure longitudinale de la <strong>muqueuse</strong> du bas œsophage / cardia</td><td><span class=\"kw-alerte\">Rupture de toute la paroi</span> œsophagienne</td></tr>\n          <tr><td>Clinique</td><td><span class=\"kw-clinique\">Vomissements</span> d'abord non sanglants, puis <span class=\"kw-clinique\">hématémèse</span></td><td><span class=\"kw-clinique\">Violente douleur thoracique</span> après efforts de <span class=\"kw-clinique\">vomissements</span>, <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">odynophagie</span>, <span class=\"kw-clinique\">emphysème sous-cutané</span> (crépitations neigeuses cervico-thoraciques)</td></tr>\n          <tr><td>Gravité</td><td>Non grave</td><td><span class=\"kw-alerte\">Très grave</span> — <span class=\"kw-alerte\">urgence</span> chirurgicale, médiastinite</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:18px 0 8px;font-size:15px;font-weight:700;\">Focus — <span class=\"kw-clinique\">Vomissements</span> de la <span class=\"kw-ci\">grossesse</span></h4>\n      <table >\n        <thead><tr><th>Forme</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Vomissements physiologiques</span></td><td><span class=\"kw-chiffre\">50 %</span> des grossesses ; au 1ᵉʳ trimestre, s'atténuant à sa fin ; dus à l'<span class=\"kw-bio\">hCG</span> et aux <span class=\"kw-bio\">estrogènes</span> ; sans retentissement sur l'état général</td></tr>\n          <tr><td><span class=\"kw-alerte\">Hyperemesis gravidarum</span></td><td>Forme sévère du 1ᵉʳ trimestre, résistante au traitement symptomatique ; <span class=\"kw-chiffre\">0,35 %</span> des grossesses ; <span class=\"kw-clinique\">déshydratation</span>, dénutrition, pertes ioniques, <span class=\"kw-bio\">cétonurie</span>, cytolyse, <span class=\"kw-clinique\">cholestase</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Vomissements du 3ᵉ trimestre</span></td><td>Imposent d'éliminer 2 urgences spécifiques : <span class=\"kw-alerte\">stéatose aiguë gravidique</span> et <span class=\"kw-alerte\">pré-éclampsie</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">📌 Chez la femme enceinte, des <span class=\"kw-clinique\">vomissements</span> répétés exposent à une <span class=\"kw-bio\">carence en vitamine B1</span> et au risque d'<span class=\"kw-alerte\">encéphalopathie de Gayet-Wernicke</span>.</div>\n\n      <h4 style=\"margin:18px 0 8px;font-size:15px;font-weight:700;\">Focus — Syndrome d'hyperemesis cannabinoïde</h4>\n      <p>Survient chez le <strong>consommateur chronique de cannabis</strong>. Élément évocateur : un soulagement par des <span class=\"kw-clinique\">bains ou douches chaudes compulsifs</span>. <span class=\"kw-clinique\">Évolution</span> en <strong>3 phases</strong> :</p>\n      <ul>\n        <li><strong>Phase initiale</strong> — <span class=\"kw-clinique\">nausées</span> matinales, douleurs abdominales mal systématisées.</li>\n        <li><strong>Phase d'état</strong> — <span class=\"kw-clinique\">vomissements incoercibles</span>, <span class=\"kw-clinique\">nausées</span> intenses, douleurs abdominales « en coup de poignard » conduisant aux urgences.</li>\n        <li><strong>Phase de récupération</strong>.</li>\n      </ul>\n      <p><span class=\"kw-clinique\">Les</span> symptômes disparaissent à l'<span class=\"kw-ttt\">arrêt de la consommation</span> ; récidive en l'absence de <span class=\"kw-ttt\">sevrage</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 354 — Syndrome occlusif · 358 — <span class=\"kw-clinique\">Pancréatite aiguë</span> · 277 — Lithiase biliaire · 303 — Tumeur estomac · 308 — Tumeur pancréas · 268 — Hypercalcémie · 267 — Trouble de l'équilibre acido-basique - Désordre hydro-électrolytique · 245 — Insuffisance surrénale · 242 — Hyperthyroïdie · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 25 — <span class=\"kw-ci\">Grossesse</span> extra-utérine · 299 — Tumeur intracranienne · 151 — <span class=\"kw-clinique\">Méningite</span> - méningoencéphalite · 99 — Migraine - névralgie trijumeau - algie face</em></p>","frequence":0},{"id":"274-8","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge médicamenteuse (indication, non indication) et non médicamenteuse","contenu":"<p>Comprendre le traitement <span class=\"kw-etio\">médicamenteux</span> suppose de connaître la physiologie du <span class=\"kw-clinique\">vomissement</span> : un <span class=\"kw-def\">centre du vomissement</span>, situé dans la substance réticulée du tronc cérébral, coordonne le réflexe. Il est alimenté par quatre types d'afférences — la <strong>zone chémoréceptrice</strong> (<span class=\"kw-def\">area postrema</span>, plancher du 4ᵉ ventricule), l'<strong>appareil vestibulaire</strong>, <span class=\"kw-clinique\">les</span> <strong>voies digestives périphériques</strong> (nerfs vague et sympathique) et les <strong>voies centrales</strong> (cortex). À chaque voie correspondent des neuromédiateurs, donc des cibles thérapeutiques.</p>\n\n      <h4 style=\"margin:16px 0 8px;font-size:15px;font-weight:700;\">Stratégie médicamenteuse selon le mécanisme</h4>\n      <table >\n        <thead><tr><th>Voie stimulée</th><th>Médiateurs</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td>Zone gâchette chémoréceptrice (<span class=\"kw-def\">CTZ / area postrema</span>) — médicaments, causes métaboliques, <span class=\"kw-ttt\">radiothérapie</span></td><td>Dopamine, sérotonine, substance P</td><td><span class=\"kw-ttt\">Antidopaminergiques</span> (<span class=\"kw-ttt\">métoclopramide</span>, métopimazine, <span class=\"kw-ttt\">halopéridol</span>, chlorpromazine, <span class=\"kw-ttt\">olanzapine</span>), <span class=\"kw-ttt\">sétrons</span> (<span class=\"kw-ttt\">ondansétron</span>), <span class=\"kw-ttt\">aprépitant</span> (anti-substance P)</td></tr>\n          <tr><td>Système <span class=\"kw-clinique\">vestibulaire</span> — mal des transports, Ménière, VPPB</td><td>Acétylcholine, histamine</td><td><span class=\"kw-ttt\">Anticholinergiques</span> (scopolamine), <span class=\"kw-ttt\">antihistaminiques</span> (diphenhydramine, hydroxyzine)</td></tr>\n          <tr><td>Voies périphériques digestives — distension, occlusion, gastroparésie</td><td>Sérotonine, <span class=\"kw-ttt\">dopamine</span></td><td><span class=\"kw-ttt\">Gastrokinétiques</span> (<span class=\"kw-ttt\">métoclopramide</span>, métopimazine, <span class=\"kw-ttt\">dompéridone</span>), <span class=\"kw-ttt\">érythromycine IV</span> (stimulation de la vidange gastrique)</td></tr>\n          <tr><td>Stimulation centrale — <span class=\"kw-alerte\">HTIC</span>, lésions intracrâniennes, <span class=\"kw-clinique\">vomissements</span> anticipatoires</td><td>Afférences corticales</td><td>Traitement étiologique : <span class=\"kw-ttt\">corticoïdes</span>, <span class=\"kw-ttt\">mannitol</span> (anti-œdémateux), <span class=\"kw-ttt\">radiothérapie</span> en cas de syndrome de <span class=\"kw-clinique\">masse</span> <span class=\"kw-etio\">tumorale</span> ; <span class=\"kw-ttt\">benzodiazépines</span> pour <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">vomissements</span> anticipatoires de <span class=\"kw-ttt\">chimiothérapie</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:16px 0 8px;font-size:15px;font-weight:700;\">Mesures non médicamenteuses et générales</h4>\n      <ul>\n        <li><strong>Alimentation</strong> — fractionnée, légère, froide, sans odeurs ; <span class=\"kw-clinique\">soins de bouche</span> ; électrostimulation du nerf vague (approches complémentaires : acupuncture).</li>\n        <li><strong><span class=\"kw-ttt\">Sonde nasogastrique</span> d'aspiration</strong> — 3 indications : <span class=\"kw-clinique\">troubles de la conscience</span>, <span class=\"kw-clinique\">vomissements abondants</span>, <span class=\"kw-alerte\">urgence chirurgicale</span> (occlusion).</li>\n      </ul>\n\n      <h4 style=\"margin:16px 0 8px;font-size:15px;font-weight:700;\">Traitement <span class=\"kw-etio\">médicamenteux</span> : indication ou non</h4>\n      <table >\n        <thead><tr><th>Décision</th><th>Situation</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Indiqué</strong></td><td><span class=\"kw-clinique\">Vomissements</span> <span class=\"kw-clinique\">très gênants</span> ou exposant à un <span class=\"kw-alerte\">risque de complications graves</span> ; voie per os, IV ou rectale</td></tr>\n          <tr><td><strong>Non indiqué</strong></td><td><span class=\"kw-clinique\">Vomissements</span> isolés, bien tolérés, sans retentissement — privilégier alors <span class=\"kw-clinique\">les</span> seules mesures non médicamenteuses</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:16px 0 8px;font-size:15px;font-weight:700;\">Neuroleptiques antidopaminergiques (anti-D2)</h4>\n      <table >\n        <thead><tr><th>Molécule</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Métopimazine</span></td><td>Activité antidopaminergique élective — très faible passage de la barrière hémato-encéphalique</td></tr>\n          <tr><td><span class=\"kw-ttt\">Dompéridone</span></td><td>Stimule la motilité gastrique ; <span class=\"kw-ci\">contre-indiquée en cas d'allongement du QTc</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Métoclopramide</span></td><td>Stimule la motricité gastrique, effet antidopaminergique central et périphérique, effet cholinergique. <strong>EI :</strong> sédation, hyperprolactinémie, <span class=\"kw-clinique\">syndrome extrapyramidal</span> (<span class=\"kw-clinique\">dystonies</span> / dyskinésies aiguës ou tardives). <strong>CI :</strong> <span class=\"kw-ci\">enfant, phéochromocytome, association à la lévodopa, consommation d'alcool, ATCD de dyskinésie tardive</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">📌 <span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">corticoïdes</span> sont largement utilisés (action multifactorielle). Les <span class=\"kw-clinique\">vomissements</span> chimio-induits relèvent d'une association : <span class=\"kw-ttt\">sétrons</span> + <span class=\"kw-ttt\">aprépitant</span> + <span class=\"kw-ttt\">corticoïdes</span>, ± <span class=\"kw-ttt\">métoclopramide</span> ou <span class=\"kw-ttt\">alizapride</span>.</div>\n\n      <h4 style=\"margin:18px 0 8px;font-size:15px;font-weight:700;\">Focus — <span class=\"kw-clinique\">Vomissements</span> induits par <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">opioïdes</span></h4>\n      <p>Effet indésirable <strong>fréquent</strong> — <span class=\"kw-chiffre\">1/3 à 1/2 des patients</span> — par stimulation de la <span class=\"kw-def\">zone chémoréceptrice</span> (<span class=\"kw-ttt\">dopamine</span>, sérotonine, substance P) et action vestibulaire. Ils s'<strong>estompent spontanément en <span class=\"kw-chiffre\">2 à 3 semaines</span></strong>.</p>\n      <table >\n        <thead><tr><th>Temps</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Préventif</strong></td><td>Anti-émétique conseillé mais <span class=\"kw-clinique\">non systématique</span> — <span class=\"kw-ttt\">gastrokinétique</span> (<span class=\"kw-ttt\">dompéridone</span>, <span class=\"kw-ttt\">métoclopramide</span> ou métopimazine), dès le début du traitement opioïde et pendant <span class=\"kw-chiffre\">8 à 15 jours</span></td></tr>\n          <tr><td><strong>Curatif</strong></td><td><span class=\"kw-clinique\">Vomissements</span> installés malgré <span class=\"kw-clinique\">les</span> gastrokinétiques : <span class=\"kw-ttt\">neuroleptiques à action centrale</span> (<span class=\"kw-ttt\">halopéridol</span> ou chlorpromazine à faible dose — prudence chez le sujet âgé), <span class=\"kw-ttt\">corticoïdes</span>, <span class=\"kw-ttt\">sétrons</span> (hors AMM, rarement utilisés), <span class=\"kw-ttt\">dropéridol IV</span> si <span class=\"kw-ttt\">morphine</span> IV</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">📌 Si <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">vomissements</span> <strong>persistent</strong> malgré le traitement symptomatique, ne pas les rapporter aux <span class=\"kw-ttt\">opioïdes</span> par défaut : rechercher une <span class=\"kw-alerte\">autre cause</span> (trouble métabolique, <span class=\"kw-alerte\">occlusion intestinale</span>…).</div>\n\n      <h4 style=\"margin:18px 0 8px;font-size:15px;font-weight:700;\">Focus — Traitement des <span class=\"kw-clinique\">vomissements</span> de la <span class=\"kw-ci\">grossesse</span></h4>\n      <p>La prise en charge des <span class=\"kw-clinique\">vomissements</span> gravidiques est d'abord <strong>non médicamenteuse</strong> ; le traitement <span class=\"kw-etio\">médicamenteux</span> repose sur des molécules propres, distinctes des antiémétiques usuels.</p>\n      <table >\n        <thead><tr><th>Volet</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Mesures hygiéno-diététiques</span></td><td>Éviter <span class=\"kw-clinique\">les</span> odeurs fortes ; <strong>casser le cercle vicieux du jeûne</strong> ; privilégier les aliments qui « passent » (soupes, féculents, gingembre) ; <span class=\"kw-clinique\">fractionner</span> — petites quantités fréquentes, manger lentement, ne pas se coucher juste après le repas</td></tr>\n          <tr><td><span class=\"kw-ttt\">Traitement médicamenteux</span></td><td><strong>Référence :</strong> <span class=\"kw-ttt\">pyridoxine (vitamine B6)</span>, seule ou associée à la <span class=\"kw-ttt\">doxylamine</span> ; en alternative, <span class=\"kw-ttt\">antihistaminiques H1</span> (hydroxyzine). <span class=\"kw-clinique\">Les</span> antiémétiques classiques (<span class=\"kw-ttt\">métoclopramide</span>, métopimazine, <span class=\"kw-ttt\">dompéridone</span>) sont <span class=\"kw-ci\">peu efficaces et déconseillés en 1ʳᵉ intention</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Hospitalisation</span></td><td>Si <span class=\"kw-alerte\">perte de poids importante</span> ou <span class=\"kw-alerte\">intolérance alimentaire totale</span> (hyperemesis gravidarum)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">📌 Bien expliquer au couple qu'il s'agit d'une <strong>pathologie hormonale</strong>, et non psychiatrique : ce n'est pas un rejet de la <span class=\"kw-ci\">grossesse</span>. Proscrire l'<span class=\"kw-def\">isolement</span> et <span class=\"kw-clinique\">les</span> mesures de privation (famille, téléphone).</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 24 — Complications de la grossesse</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Nourrisson <span class=\"q\">— <span class=\"kw-clinique\">vomissement</span> <span class=\"kw-clinique\">bilieux</span></span></strong></p><p>avis chir et <span class=\"kw-imagerie\">imagerie</span> sans délai</p><ul><li><span class=\"kw-alerte\">drapeau rouge</span> chirurgical (<span class=\"kw-alerte\">volvulus sur malrotation</span>, <span class=\"kw-alerte\">IIA</span>, <span class=\"kw-alerte\">occlusion</span>)</li></ul><p><strong><span class=\"kw-clinique\">Vomissements</span> <span class=\"kw-clinique\">en jet matinaux</span> + <span class=\"kw-clinique\">céphalées</span></strong></p><ul><li><span class=\"kw-alerte\">HTIC</span> suspecte → <span class=\"kw-imagerie\">TDM cérébrale</span> en <span class=\"kw-alerte\">urgence</span></li></ul><p><strong>Nourrisson <span class=\"kw-chiffre\">3 à 5 semaines</span> + <span class=\"kw-clinique\">lait caillé en jet</span> + <span class=\"kw-alerte\">cassure pondérale</span></strong></p><p>correction <span class=\"kw-bio\">hydro-électrolytique</span> puis <span class=\"kw-ttt\">pyloromyotomie</span> dans la journée</p><ul><li><span class=\"kw-alerte\">sténose du pylore</span></li></ul><p><strong><span class=\"kw-bio\">Hypoglycémie</span> / <span class=\"kw-alerte\">acidocétose diabétique</span> / suspicion <span class=\"kw-etio\">intoxication (CO, médicaments)</span></strong></p><p><span class=\"kw-bio\">glycémie</span>, <span class=\"kw-bio\">BU</span>, <span class=\"kw-bio\">iono</span> immédiats</p><ul><li><span class=\"kw-alerte\">urgence</span> métabolique</li></ul><p><strong><span class=\"kw-clinique\">Douleur thoracique violente</span> + <span class=\"kw-clinique\">emphysème sous-cutané</span> post-<span class=\"kw-clinique\">vomissement</span></strong></p><p><span class=\"kw-alerte\">urgence</span> chirurgicale (<span class=\"kw-alerte\">médiastinite</span>)</p><ul><li><span class=\"kw-alerte\">syndrome de Boerhaave</span></li></ul><p><strong>Femme enceinte avec <span class=\"kw-clinique\">vomissements répétés</span> + <span class=\"kw-clinique\">confusion</span></strong></p><p><span class=\"kw-ttt\">vitamine B1 IV</span> sans attendre</p><ul><li>évoquer une <span class=\"kw-alerte\">encéphalopathie de Gayet-Wernicke</span> (carence <span class=\"kw-bio\">B1</span>)</li></ul>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-clinique\">vomissements</span> isolés bien tolérés, <span class=\"kw-etio\">GEA</span> simple sans <span class=\"kw-clinique\">déshydratation</span>, consigne de reconsultation.<br><strong>Hospit pédiatrie :</strong> <span class=\"kw-alerte\">déshydratation</span>, suspicion de <span class=\"kw-alerte\">sténose du pylore</span>, vomissements répétés du nourrisson, <span class=\"kw-def\">terrain</span> fragile.<br><strong>Hospit chirurgicale :</strong> <span class=\"kw-clinique\">vomissement</span> <span class=\"kw-clinique\">bilieux</span> du nourrisson, <span class=\"kw-alerte\">volvulus</span> / <span class=\"kw-alerte\">IIA</span> / <span class=\"kw-alerte\">occlusion</span> / <span class=\"kw-alerte\">appendicite compliquée</span>, <span class=\"kw-alerte\">Boerhaave</span>.<br><strong>Hospit obstétricale :</strong> <span class=\"kw-alerte\">hyperemesis gravidarum</span> avec <span class=\"kw-alerte\">perte de poids importante</span> ou <span class=\"kw-alerte\">intolérance alimentaire totale</span> ; vomissements du <span class=\"kw-chiffre\">3ᵉ trimestre</span> (éliminer <span class=\"kw-alerte\">stéatose aiguë gravidique</span>, <span class=\"kw-alerte\">pré-éclampsie</span>).<br><strong><span class=\"kw-alerte\">Réanimation</span> :</strong> <span class=\"kw-alerte\">choc hypovolémique</span>, <span class=\"kw-alerte\">troubles de la conscience</span>, <span class=\"kw-alerte\">médiastinite</span> sur Boerhaave, <span class=\"kw-alerte\">pneumopathie d'inhalation</span> (Mendelson).</p>","redflags":"<ul><li>Nourrisson — <span class=\"kw-clinique\">vomissement</span> <span class=\"kw-clinique\">bilieux</span> (<span class=\"kw-alerte\">drapeau rouge</span> <span class=\"kw-alerte\">chirurgical</span> : volvulus sur malrotation, IIA, occlusion)</li><li><span class=\"kw-clinique\">Vomissements</span> <span class=\"kw-clinique\">en jet matinaux</span> sans <span class=\"kw-clinique\">nausée</span> ni haut-le-cœur → <span class=\"kw-alerte\">HTIC</span> (tumeur cérébrale, HSD/HED)</li><li><span class=\"kw-clinique\">Vomissements</span> <span class=\"kw-clinique\">fécaloïdes</span> → <span class=\"kw-alerte\">occlusion basse</span> (grêle distal, côlon) ou <span class=\"kw-clinique\">fistule</span> gastro-colique</li><li>Nourrisson <span class=\"kw-chiffre\">3-5 semaines</span> + <span class=\"kw-clinique\">jet</span> + <span class=\"kw-clinique\">lait caillé non bilieux</span> + <span class=\"kw-alerte\">cassure pondérale</span> → <span class=\"kw-alerte\">sténose hypertrophique du pylore</span></li><li><span class=\"kw-clinique\">Douleur thoracique violente</span> + <span class=\"kw-clinique\">dyspnée</span> + <span class=\"kw-clinique\">emphysème sous-cutané cervico-thoracique</span> post-<span class=\"kw-clinique\">vomissements</span> → <span class=\"kw-alerte\">syndrome de Boerhaave</span></li><li><span class=\"kw-alerte\">Déshydratation</span> sévère + <span class=\"kw-alerte\">AEG</span> + <span class=\"kw-bio\">alcalose métabolique hypochlorémique</span> → retentissement décompensé</li><li><span class=\"kw-clinique\">Vomissements</span> répétés de la femme enceinte + <span class=\"kw-clinique\">confusion</span> / signes neuro → <span class=\"kw-alerte\">encéphalopathie de Gayet-Wernicke</span> (carence <span class=\"kw-bio\">B1</span>)</li><li><span class=\"kw-clinique\">Vomissements</span> sous <span class=\"kw-ttt\">opioïdes</span> qui <strong>persistent</strong> malgré le traitement symptomatique → rechercher une <span class=\"kw-alerte\">autre cause</span> (occlusion, trouble métabolique)</li><li><span class=\"kw-clinique\">Troubles de la conscience</span> ou neuro associés avec <span class=\"kw-clinique\">vomissements</span> → risque de <span class=\"kw-alerte\">pneumopathie d'inhalation (Mendelson, SDRA)</span> → SNG d'aspiration</li></ul>","principes":"<p><strong>Mesures non médicamenteuses d'abord</strong> — <span class=\"kw-clinique\">réhydratation</span> orale fractionnée privilégiée, <span class=\"kw-clinique\">fractionnement des repas</span> (légers, froids, sans odeurs), <span class=\"kw-clinique\">soins de bouche</span>.<br><strong>Médicament <span class=\"kw-clinique\">non systématique</span> :</strong> indiqué si <span class=\"kw-clinique\">vomissements</span> très gênants ou exposant à un risque de complications graves ; choix selon le <strong>mécanisme</strong> stimulé (CTZ, vestibulaire, périphérique, central).<br><strong><span class=\"kw-ttt\">Sonde nasogastrique</span> d'aspiration — 3 indications :</strong> <span class=\"kw-clinique\">troubles de la conscience</span>, <span class=\"kw-clinique\">vomissements abondants</span>, <span class=\"kw-alerte\">urgence chirurgicale (occlusion)</span>.</p><p><strong>Enfant</strong></p><ul><li>seul l'<span class=\"kw-ttt\">ondansétron</span> a démontré son efficacité</li><li><span class=\"kw-def\">AMM</span> restreinte aux <span class=\"kw-clinique\">vomissements postopératoires</span> et aux <span class=\"kw-clinique\">vomissements chimio-induits</span>. <span class=\"kw-ci\">Métoclopramide contre-indiqué chez l'enfant</span> (<span class=\"kw-clinique\">syndrome extrapyramidal</span>).</li></ul><p><strong>Adulte <span class=\"q\">— zone chémoréceptrice (médicaments, métabolique)</span></strong></p><ul><li><span class=\"kw-ttt\">antidopaminergiques</span> (<span class=\"kw-ttt\">métoclopramide</span>, <span class=\"kw-ttt\">métopimazine</span>, <span class=\"kw-ttt\">halopéridol</span>), <span class=\"kw-ttt\">sétrons</span> (<span class=\"kw-ttt\">ondansétron</span>), <span class=\"kw-ttt\">aprépitant</span> (anti-substance P).</li></ul><p><strong>Vestibulaire <span class=\"q\">(mal des transports, Ménière, VPPB)</span></strong></p><ul><li><span class=\"kw-ttt\">anticholinergiques</span> (<span class=\"kw-ttt\">scopolamine</span>), <span class=\"kw-ttt\">antihistaminiques</span> (<span class=\"kw-ttt\">hydroxyzine</span>, <span class=\"kw-ttt\">diphenhydramine</span>).</li></ul><p><strong>Périphérique digestif <span class=\"q\">(distension, gastroparésie)</span></strong></p><ul><li><span class=\"kw-ttt\">gastrokinétiques</span> (<span class=\"kw-ttt\">métoclopramide</span>, <span class=\"kw-ttt\">métopimazine</span>, <span class=\"kw-ttt\">dompéridone</span>)</li><li><span class=\"kw-ttt\">érythromycine IV</span>.</li></ul><p><strong>Stimulation centrale <span class=\"q\">(<span class=\"kw-alerte\">HTIC</span>)</span></strong></p><ul><li>traitement étiologique — <span class=\"kw-ttt\">corticoïdes</span>, <span class=\"kw-ttt\">mannitol</span> (anti-œdémateux), <span class=\"kw-ttt\">radiothérapie</span> si <span class=\"kw-clinique\">masse</span> <span class=\"kw-etio\">tumorale</span></li><li><span class=\"kw-ttt\">benzodiazépines</span> pour <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">vomissements</span> anticipatoires de chimio.</li></ul><p><strong>Femme enceinte <span class=\"q\">(1ʳᵉ intention)</span></strong></p><ul><li>mesures hygiéno-diététiques + <span class=\"kw-ttt\">pyridoxine (vitamine B6)</span> seule ou associée à la <span class=\"kw-ttt\">doxylamine</span></li><li>alternative <span class=\"kw-ttt\">antihistaminiques H1</span> (hydroxyzine). <span class=\"kw-ci\">Métoclopramide, métopimazine, dompéridone : peu efficaces et déconseillés en 1ʳᵉ intention</span>.</li></ul><p><strong>Sous <span class=\"kw-ttt\">opioïdes</span></strong></p><ul><li><span class=\"kw-ttt\">gastrokinétique</span> préventif (<span class=\"kw-ttt\">dompéridone</span>, <span class=\"kw-ttt\">métoclopramide</span> ou métopimazine) <span class=\"kw-chiffre\">8 à 15 jours</span></li><li>si persistance malgré ttt → <span class=\"kw-ttt\">halopéridol</span> faible dose, <span class=\"kw-ttt\">corticoïdes</span>, <span class=\"kw-ttt\">sétrons</span> (hors AMM), <span class=\"kw-ttt\">dropéridol IV</span> si <span class=\"kw-ttt\">morphine</span> IV.</li></ul><p><strong>Chimio cytotoxiques</strong></p><ul><li>association <span class=\"kw-ttt\">sétrons</span> + <span class=\"kw-ttt\">aprépitant</span> + <span class=\"kw-ttt\">corticoïdes</span>, ± <span class=\"kw-ttt\">métoclopramide</span> ou <span class=\"kw-ttt\">alizapride</span>.</li></ul><p><strong>Précautions anti-D2</strong></p><ul><li><span class=\"kw-ci\">dompéridone contre-indiquée si allongement du QTc</span></li><li><span class=\"kw-ci\">métoclopramide : CI chez l'enfant, en cas de phéochromocytome, association à la lévodopa, alcool, ATCD de dyskinésie tardive</span>.</li></ul>","suivi":"<p><strong>Aigu :</strong> <span class=\"kw-def\">surveillance</span> <span class=\"kw-clinique\">poids</span>, <span class=\"kw-clinique\">hydratation</span> (pli cutané, diurèse), <span class=\"kw-clinique\">FC / TA</span> ; <span class=\"kw-bio\">iono sang</span> + <span class=\"kw-bio\">créatininémie</span> si <span class=\"kw-clinique\">vomissements</span> prolongés ou suspicion de <span class=\"kw-bio\">alcalose hypochlorémique hypokaliémique</span>.<br><strong>Sous <span class=\"kw-ttt\">opioïdes</span> :</strong> <span class=\"kw-clinique\">les</span> vomissements s'estompent en <span class=\"kw-chiffre\">2 à 3 semaines</span> ; gastrokinétique préventif <span class=\"kw-chiffre\">8-15 jours</span> dès l'instauration.<br><strong>Persistance malgré traitement symptomatique :</strong> NE PAS s'arrêter à l'effet indésirable — rechercher une <span class=\"kw-alerte\">autre cause</span> (<span class=\"kw-alerte\">occlusion intestinale</span>, trouble métabolique, <span class=\"kw-alerte\">HTIC</span> évolutive).<br><strong>Femme enceinte :</strong> surveillance <span class=\"kw-clinique\">poids</span>, <span class=\"kw-bio\">cétonurie</span>, <span class=\"kw-bio\">iono</span> ; en cas de vomissements répétés, prévention de la <span class=\"kw-alerte\">carence en B1</span> (<span class=\"kw-ttt\">supplémentation vitamine B1</span>) pour éviter <span class=\"kw-alerte\">Gayet-Wernicke</span>.<br><strong>Post-épisode sévère :</strong> dépister les complications — <span class=\"kw-alerte\">œsophagite</span>, <span class=\"kw-alerte\">syndrome de Mallory-Weiss</span>, perte d'émail, dénutrition ; revoir l'observance des traitements oraux interrompus.</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Vomissements de l'enfant — Anamnèse + examen clinique orientés (pas d'examen complémentaire systématique)","detail":"<h4>CAT — <span class=\"kw-clinique\">Vomissements</span> de l'enfant — Démarche diagnostique : éliminer <span class=\"kw-clinique\">les</span> urgences avant toute cause banale</h4>","branches":[{"to":"q-bilieux","label":"Analyse du caractère et des signes","color":"blue"}]},{"id":"q-bilieux","kind":"decision","label":"Vomissement BILIEUX ? — Drapeau rouge chirurgical n°1 chez le nourrisson","branches":[{"to":"t-chir","label":"Oui (bilieux)","color":"red"},{"to":"q-urgence-non-inf","label":"Non (non bilieux)","color":"blue"}]},{"id":"t-chir","kind":"terminal","label":"Urgence chirurgicale","color":"red","detail":"<h4>Causes à évoquer</h4><ul><li><span class=\"kw-alerte\">Volvulus sur malrotation intestinale</span> (nouveau-né, nourrisson)</li><li><span class=\"kw-alerte\">Invagination intestinale aiguë (IIA)</span></li><li><span class=\"kw-alerte\">Occlusion sur bride</span>, <span class=\"kw-alerte\">hernie inguinale étranglée</span></li><li><span class=\"kw-alerte\">Atrésie duodéno-jéjunale</span>, <span class=\"kw-alerte\">iléus méconial</span> (nouveau-né)</li><li><span class=\"kw-etio\">Maladie de Hirschsprung</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Échographie abdominale</span> + <span class=\"kw-imagerie\">ASP</span> en 1ʳᵉ intention</li><li><span class=\"kw-imagerie\">TDM abdomino-pelvienne</span> si syndrome occlusif confirmé</li><li><span class=\"kw-bio\">Iono sang</span>, <span class=\"kw-bio\">gaz du sang</span> (retentissement)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-clinique\">À jeun strict</span>, <span class=\"kw-ttt\">SNG d'aspiration</span></li><li><span class=\"kw-ttt\">Réhydratation IV</span>, correction des troubles ioniques</li><li>Avis <span class=\"kw-clinique\">chirurgical pédiatrique</span> sans délai</li></ul><h4>Piège</h4><ul><li>Le caractère <strong>bilieux</strong> chez le nourrisson est un signe d'alarme à lui seul — il oriente vers une obstruction <strong>en aval du pylore</strong>. Ne jamais le banaliser.</li></ul>"},{"id":"q-urgence-non-inf","kind":"decision","label":"Signe d'urgence non infectieux ? — HTIC · sténose du pylore · cause métabolique / toxique","branches":[{"to":"t-htic","label":"En jet matinal + céphalées","color":"red"},{"to":"t-pylore","label":"3-5 sem + jet + lait caillé + cassure poids","color":"red"},{"to":"t-metabo","label":"Hypoglycémie / acidocétose / intox","color":"red"},{"to":"q-infect","label":"Aucun de ces signes","color":"blue"}]},{"id":"t-htic","kind":"terminal","label":"HTIC suspecte","color":"red","detail":"<h4>Clinique évocatrice</h4><ul><li><span class=\"kw-clinique\">Vomissements</span> <span class=\"kw-clinique\">matinaux, en jet</span>, sans <span class=\"kw-clinique\">nausée</span> ni haut-le-cœur</li><li><span class=\"kw-clinique\">Céphalées</span> matinales, signes neurologiques focaux</li><li>Modification du comportement, du caractère ou des performances scolaires</li></ul><h4>Causes</h4><ul><li><span class=\"kw-etio\">Tumeur cérébrale</span> (fosse postérieure ++)</li><li><span class=\"kw-alerte\">Hématome sous-dural</span> ou <span class=\"kw-alerte\">extradural</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">TDM cérébrale</span> en <span class=\"kw-alerte\">urgence</span> (puis <span class=\"kw-imagerie\">IRM cérébrale</span>) ; <span class=\"kw-imagerie\">fond d'œil</span> (<span class=\"kw-clinique\">œdème</span> papillaire).</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span> urgente ; avis neurochirurgical ; traitement étiologique (<span class=\"kw-ttt\">corticoïdes</span>, <span class=\"kw-ttt\">mannitol</span>, <span class=\"kw-ttt\">radiothérapie</span> selon cause).</li></ul>"},{"id":"t-pylore","kind":"terminal","label":"Sténose hypertrophique du pylore","color":"red","detail":"<h4><span class=\"kw-def\">Terrain</span></h4><ul><li>Jeune nourrisson — <span class=\"kw-chiffre\">intervalle libre de 3 à 5 semaines</span> après la naissance</li><li><span class=\"kw-clinique\">Prédominance masculine</span> ; ATCD familiaux parfois</li><li>Aggravation <strong>progressive</strong></li></ul><h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Vomissements</span> <span class=\"kw-clinique\">à distance du repas (30-60 min)</span>, abondants, <span class=\"kw-clinique\">en jet explosifs</span></li><li><span class=\"kw-clinique\">Lait caillé blanc non teinté de bile</span> (signe clé)</li><li><span class=\"kw-alerte\">Cassure de la courbe de poids</span> contrastant avec un <span class=\"kw-clinique\">appétit conservé</span></li><li>Palpation d'une <span class=\"kw-clinique\">olive pylorique</span> + ondulations péristaltiques visibles</li><li><span class=\"kw-alerte\">Déshydratation</span> et <span class=\"kw-alerte\">dénutrition</span> variables</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Gaz du sang : alcalose métabolique hypochlorémique</span></li><li><span class=\"kw-imagerie\">Échographie abdominale</span> (confirmation) : aspect en « cocarde », <span class=\"kw-radio\">épaississement du muscle ≥ 4 mm</span>, allongement du canal pylorique, stase gastrique</li></ul><h4>Traitement</h4><ul><li><strong>1.</strong> <span class=\"kw-alerte\">Urgence</span> symptomatique : correction de la <span class=\"kw-alerte\">déshydratation</span> et des <span class=\"kw-bio\">troubles ioniques</span></li><li><strong>2.</strong> Étiologique chirurgical : <span class=\"kw-ttt\">pyloromyotomie longitudinale extramuqueuse</span></li></ul>"},{"id":"t-metabo","kind":"terminal","label":"Urgence métabolique ou toxique","color":"red","detail":"<h4>Causes</h4><ul><li><span class=\"kw-bio\">Hypoglycémie</span></li><li><span class=\"kw-alerte\">Acidocétose diabétique</span> inaugurale</li><li><span class=\"kw-etio\">Intoxication médicamenteuse</span> ou au <span class=\"kw-etio\">CO</span></li><li><span class=\"kw-etio\">Hypervitaminoses A et D</span></li><li>Maladies métaboliques héréditaires (<span class=\"kw-etio\">galactosémie</span>, <span class=\"kw-etio\">fructosémie</span>, <span class=\"kw-etio\">anomalies du cycle de l'urée</span>)</li><li><span class=\"kw-etio\">Hyperplasie congénitale des surrénales</span></li></ul><h4>Paraclinique immédiat</h4><ul><li><span class=\"kw-bio\">Glycémie capillaire</span> + <span class=\"kw-bio\">BU</span> (<span class=\"kw-bio\">cétonurie</span>, <span class=\"kw-bio\">glycosurie</span>)</li><li><span class=\"kw-bio\">Iono sang</span>, <span class=\"kw-bio\">gaz du sang</span>, <span class=\"kw-bio\">lactate</span></li><li>Dosages <span class=\"kw-bio\">toxicologiques</span> orientés ; <span class=\"kw-bio\">HbCO</span> si suspicion CO</li><li><span class=\"kw-imagerie\">ECG</span> selon contexte</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span>, correction de la cause métabolique ; <span class=\"kw-ttt\">resucrage</span> ou <span class=\"kw-ttt\">insulinothérapie</span> selon contexte ; <span class=\"kw-ttt\">décontamination</span> et antidote selon <span class=\"kw-etio\">toxique</span>.</li></ul>"},{"id":"q-infect","kind":"decision","label":"Syndrome infectieux ? — Fièvre, AEG, foyer infectieux clinique","branches":[{"to":"t-infect","label":"Oui (fébrile)","color":"amber"},{"to":"t-standard","label":"Non (apyrétique)","color":"green"}]},{"id":"t-infect","kind":"terminal","label":"Cause infectieuse","color":"amber","detail":"<h4>Causes <span class=\"kw-clinique\">les</span> plus fréquentes</h4><ul><li><span class=\"kw-etio\">Gastroentérite</span> ++ — <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">vomissements</span> peuvent précéder la diarrhée de plusieurs heures</li><li><span class=\"kw-etio\">Infections ORL</span> ++ — otite, rhinopharyngite, angine, stomatite</li></ul><h4>Causes à ne pas méconnaître</h4><ul><li><span class=\"kw-etio\">Pyélonéphrite aiguë (PNA)</span></li><li><span class=\"kw-alerte\">Méningite</span> / <span class=\"kw-clinique\">méningo-encéphalite</span></li><li><span class=\"kw-etio\">Appendicite</span>, <span class=\"kw-alerte\">péritonite</span></li><li><span class=\"kw-etio\">Hépatite</span>, <span class=\"kw-etio\">coqueluche émétisante</span></li><li><span class=\"kw-alerte\">ECUN</span> (prématuré)</li></ul><h4>Paraclinique selon orientation</h4><ul><li><span class=\"kw-bio\">BU</span>, <span class=\"kw-bio\">ECBU</span> si suspicion PNA</li><li><span class=\"kw-imagerie\">Ponction lombaire</span> si <span class=\"kw-alerte\">syndrome méningé</span></li><li><span class=\"kw-imagerie\">Échographie abdominale</span> si <span class=\"kw-clinique\">appendicite</span> suspectée</li><li><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">hémocultures</span> selon contexte</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-clinique\">Réhydratation</span> orale fractionnée (privilégiée si tolérée)</li><li>Traitement <span class=\"kw-ttt\">étiologique</span> selon le foyer (<span class=\"kw-ttt\">antibiothérapie</span> ciblée si <span class=\"kw-etio\">bactérien</span>)</li><li><span class=\"kw-ttt\">Ondansétron</span> possible en postop ou chimio uniquement (<span class=\"kw-ci\">métoclopramide contre-indiqué chez l'enfant</span>)</li></ul>"},{"id":"t-standard","kind":"terminal","label":"Démarche standard (afébrile, sans urgence)","color":"green","detail":"<h4>Étape 1 — Aigus / occasionnels</h4><ul><li>Rechercher une <span class=\"kw-etio\">allergie alimentaire</span> (forme <span class=\"kw-chiffre\">IgE</span>-médiée, <span class=\"kw-def\">SEIPA</span> aigu) ou un <span class=\"kw-etio\">RGO</span> compliqué.</li></ul><h4>Étape 2 — Chroniques / récurrents : éliminer <span class=\"kw-clinique\">les</span> erreurs diététiques</h4><ul><li>Interrogatoire alimentaire ciblé — rechercher <span class=\"kw-etio\">quantités excessives</span> et <span class=\"kw-etio\">forcing alimentaire</span> (cause banale et fréquente, à écarter avant tout bilan).</li></ul><h4>Étape 3 — Causes digestives chroniques</h4><ul><li><span class=\"kw-etio\">RGO</span></li><li><span class=\"kw-etio\">APLV</span> — forme retardée, SEIPA chronique</li><li><span class=\"kw-etio\">Maladie cœliaque</span> (cause rare de <span class=\"kw-clinique\">vomissements</span>)</li></ul><h4>Étape 4 — Causes extra-digestives chroniques</h4><ul><li><span class=\"kw-etio\">Tubulopathies</span>, <span class=\"kw-etio\">hépatopathies</span></li><li><span class=\"kw-etio\">Insuffisance cardiaque</span>, <span class=\"kw-ttt\">chimiothérapies anticancéreuses</span></li><li><span class=\"kw-def\">Vomissements cycliques</span> — épisodes intenses espacés de plusieurs semaines, sans symptôme associé</li><li><span class=\"kw-etio\">Vomissements psychogènes</span> — l'une des principales causes inexpliquées chez l'enfant</li></ul><h4>Conduite</h4><ul><li>Pas d'examen complémentaire systématique. <span class=\"kw-def\">Surveillance</span> <span class=\"kw-clinique\">poids</span> + <span class=\"kw-clinique\">hydratation</span> ; consigne de reconsultation en cas d'apparition d'un <span class=\"kw-alerte\">drapeau rouge</span> (bilieux, jet matinal, <span class=\"kw-clinique\">AEG</span>).</li></ul>"}]},"cards":[{"i":"2d7faec107ec","n":274,"o":"274-2","u":"Étiologies","t":"Connaître les principales causes de vomissements à connaître chez l’enfant","q":"Quelles sont les causes chirurgicales de vomissements aigus ou occasionnels sans syndrome infectieux chez le nourrisson et l'enfant ?","a":"<ul><li><strong>Hernie inguinale étranglée</strong></li><li><strong>Volvulus</strong></li><li><strong>Occlusion sur bride</strong></li><li><strong>Invagination intestinale aiguë (IIA)</strong></li><li><strong>Appendicite</strong></li><li><strong>Torsion du cordon spermatique ou d'annexe</strong></li></ul>"},{"i":"3e2f3e540e40","n":274,"o":"274-2","u":"Étiologies","t":"Connaître les principales causes de vomissements à connaître chez l’enfant","q":"Comment doit-on aborder l'orientation étiologique des vomissements chez l'enfant ?","a":"<p>L'orientation étiologique des vomissements chez l'enfant repose d'abord sur la distinction <strong>aigus/occasionnels</strong> versus <strong>chroniques/récurrents</strong>, puis sur la présence ou non d'un <strong>syndrome infectieux</strong>.</p>"},{"i":"436a36631f36","n":274,"o":"274-2","u":"Étiologies","t":"Connaître les principales causes de vomissements à connaître chez l’enfant","q":"Quelles sont les causes fréquentes de vomissements aigus ou occasionnels avec syndrome infectieux chez l'enfant ?","a":"<ul><li><strong>Gastroentérite</strong> (Les vomissements peuvent précéder la diarrhée de plusieurs heures).</li><li><strong>Infections ORL</strong> (otite, rhinopharyngite, angine, stomatite).</li><li>Autres infections graves comme une <strong>pyélonéphrite aiguë (PNA)</strong>, une <strong>méningite</strong>, une <strong>appendicite</strong>, une <strong>péritonite</strong>, une <strong>hépatite</strong> ou une <strong>infection respiratoire</strong> (ex: coqueluche émétisante).</li></ul>"},{"i":"5fa85d45e89d","n":274,"o":"274-2","u":"Étiologies","t":"Connaître les principales causes de vomissements à connaître chez l’enfant","q":"Devant des vomissements chroniques ou récurrents chez l'enfant, quelle est la première chose à éliminer à l'interrogatoire ?","a":"<p>Il faut éliminer en premier lieu les <strong>erreurs diététiques</strong> : <strong>quantités excessives</strong> ou <strong>forcing alimentaire</strong>.</p>"},{"i":"98682cb8613d","n":274,"o":"274-2","u":"Étiologies","t":"Connaître les principales causes de vomissements à connaître chez l’enfant","q":"Quelles sont les principales causes extra-digestives de vomissements chroniques ou récurrents chez l'enfant ?","a":"<ul><li><strong>Hypertension intracrânienne (HTIC)</strong>.</li><li><strong>Insuffisance cardiaque</strong>.</li><li><strong>Tubulopathies</strong>, <strong>hépatopathies</strong>.</li><li><strong>Chimiothérapies anticancéreuses</strong>.</li><li><strong>Acidocétose diabétique</strong>, <strong>hyperplasie congénitale des surrénales</strong>.</li><li><strong>Maladies métaboliques héréditaires</strong> : galactosémie, fructosémie, anomalies du cycle de l'urée.</li><li><strong>Vomissements cycliques</strong> (épisodes intenses, espacés de plusieurs semaines).</li><li><strong>Vomissements psychogènes</strong> (une des principales causes inexpliquées).</li></ul>"},{"i":"b67962fef66f","n":274,"o":"274-2","u":"Étiologies","t":"Connaître les principales causes de vomissements à connaître chez l’enfant","q":"Quelles sont les causes digestives de vomissements chroniques ou récurrents chez l'enfant ?","a":"<ul><li><strong>Sténose du pylore</strong> (urgence du jeune nourrisson).</li><li><strong>Reflux gastro-œsophagien (RGO)</strong>.</li><li><strong>Allergie aux protéines de lait de vache (APLV)</strong> (forme retardée, SEIPA chronique).</li><li><strong>Maladie cœliaque</strong> (cause rare).</li></ul>"},{"i":"c5f7e43a9163","n":274,"o":"274-2","u":"Étiologies","t":"Connaître les principales causes de vomissements à connaître chez l’enfant","q":"Quelles sont les étiologies neurologiques, métaboliques/toxiques ou allergiques des vomissements aigus ou occasionnels sans syndrome infectieux chez le nourrisson et l'enfant ?","a":"<ul><li><strong>Neurologique</strong> : <strong>hypertension intracrânienne (HTIC)</strong>, hématome sous-dural ou extradural, tumeur cérébrale.</li><li><strong>Métabolique/toxique</strong> : <strong>hypoglycémie</strong>, <strong>acidocétose diabétique</strong>, intoxication médicamenteuse ou au CO, hypervitaminoses A et D.</li><li><strong>Allergique</strong> : allergies alimentaires (forme IgE-médiée, SEIPA aigu).</li></ul>"},{"i":"d86876b1154e","n":274,"o":"274-2","u":"Étiologies","t":"Connaître les principales causes de vomissements à connaître chez l’enfant","q":"Quelles sont les causes de vomissements aigus ou occasionnels sans syndrome infectieux chez le nouveau-né prématuré (ECUN) ?","a":"<ul><li><strong>Atrésie duodéno-jéjunale</strong></li><li><strong>Maladie de Hirschsprung</strong></li><li><strong>Iléus méconial</strong></li><li><strong>Volvulus sur malrotation intestinale</strong></li></ul>"},{"i":"44cba8b4b426","n":274,"o":"274-6","u":"Diagnostic positif","t":"Connaître les symptômes orientant la démarche diagnostique (aiguë vs chronique)","q":"Comment définit-on le vomissement et quels sont les signes neurovégétatifs qui l'accompagnent fréquemment ?","a":"<p>Le vomissement est le rejet brutal par la bouche du contenu gastrique, par contractions cycliques et synchrones de la musculature abdominale, du diaphragme et des muscles respiratoires.</p><ul><li>Activation parasympathique : <strong>hypersalivation</strong>, <strong>bradycardie</strong>.</li><li>Activation sympathique : <strong>tachycardie</strong>, <strong>sueurs froides</strong>, <strong>pâleur</strong> par vasoconstriction cutanée, <strong>mydriase</strong>.</li></ul>"},{"i":"65cec8695386","n":274,"o":"274-6","u":"Diagnostic positif","t":"Connaître les symptômes orientant la démarche diagnostique (aiguë vs chronique)","q":"Quels sont les différents types de vomissements (ex : matinaux, post-prandiaux tardifs) et les orientations diagnostiques associées, selon la sémiologie ?","a":"<ul><li><strong>Matineau, à jeun, liquide peu glaireux, hauts-le-cœur (pituites)</strong> : Grossesse, consommation excessive d'alcool, intoxication, intolérance.</li><li><strong>Post-prandiaux tardifs répétés, aliments nauséabonds partiellement digérés</strong> : Obstruction chronique gastro-duodénale (organique ou fonctionnelle comme une gastroparésie).</li><li><strong>Fécaloïdes</strong> : Obstruction basse (grêle distal, côlon), fistule gastro-colique (exceptionnel).</li><li><strong>Per-prandiaux ou immédiatement après le repas</strong> : Cause psychogène (diagnostic d'élimination).</li><li><strong>Plutôt en fin de journée, alimentaires, précédés de nausées / ballonnements / satiété / crampes</strong> : Syndrome obstructif (obstacle organique incomplet).</li></ul>"},{"i":"8ba4c1f7240b","n":274,"o":"274-6","u":"Diagnostic positif","t":"Connaître les symptômes orientant la démarche diagnostique (aiguë vs chronique)","q":"Quelle est la différence entre un vomissement aigu et un vomissement chronique ?","a":"<p>Un vomissement est dit <strong>aigu</strong> lorsqu'il date de <strong>moins de 7 jours</strong>. Il est dit <strong>chronique</strong> lorsqu'il dure <strong>plus de 7 jours</strong> ou qu'il est récidivant.</p>"},{"i":"dc975df17f75","n":274,"o":"274-6","u":"Diagnostic positif","t":"Connaître les symptômes orientant la démarche diagnostique (aiguë vs chronique)","q":"Quelles sont les caractéristiques sémiologiques d'un vomissement pouvant orienter vers une Hypertension Intracrânienne (HTIC) ?","a":"<p>Les vomissements orientant vers une HTIC sont généralement <strong>matinaux</strong>, en <strong>jet</strong>, et surviennent <strong>sans nausée ni haut-le-cœur</strong>.</p>"},{"i":"ef0bd0ce543a","n":274,"o":"274-6","u":"Diagnostic positif","t":"Connaître les symptômes orientant la démarche diagnostique (aiguë vs chronique)","q":"Quelles sont les quatre étiologies à toujours évoquer devant tout vomissement ?","a":"<p>Les quatre étiologies à toujours évoquer devant tout vomissement, quel qu'en soit le tableau, sont : la <strong>grossesse</strong>, un <strong>médicament / toxique / drogue</strong>, une <strong>Hypertension Intracrânienne (HTIC)</strong>, ou une <strong>cause métabolique</strong> (insuffisance rénale aiguë, insuffisance surrénalienne).</p>"},{"i":"039c67a55b36","n":274,"o":"274-7","u":"Étiologies","t":"Connaître les causes principales digestives et extradigestives (médicamenteux, métabolique, neurologique, ..)","q":"Quelles sont les principales causes extradigestives de vomissements chroniques chez l'adulte ?","a":"<p>Les principales causes extradigestives de vomissements chroniques (plus de 7 jours ou récidivants) chez l'adulte incluent :</p><ul><li><strong>Neurologiques</strong> : <strong>HTIC</strong>, <strong>épilepsie</strong>.</li><li><strong>Psychiatriques</strong> : <strong>anorexie mentale</strong>, <strong>boulimie</strong>, <strong>vomissements psychogènes</strong>.</li><li><strong>Autres</strong> : <strong>grossesse</strong> (1er trimestre), <strong>hyperemesis aux cannabinoïdes</strong>, <strong>vomissements cataméniaux</strong>, <strong>syndrome des vomissements cycliques idiopathiques</strong>, <strong>chimiothérapies cytotoxiques</strong>, <strong>autres médicaments</strong> (digitaliques, opiacés).</li></ul>"},{"i":"5d2891f7edc0","n":274,"o":"274-7","u":"Étiologies","t":"Connaître les causes principales digestives et extradigestives (médicamenteux, métabolique, neurologique, ..)","q":"Quelles sont les principales causes extradigestives de vomissements aigus chez l'adulte ?","a":"<p>Les principales causes extradigestives de vomissements aigus (moins de 7 jours) chez l'adulte incluent :</p><ul><li><strong>Métaboliques</strong> : <strong>hyponatrémie</strong>, <strong>hypercalcémie</strong>, <strong>hypoglycémie</strong>, <strong>insuffisance rénale aiguë</strong>.</li><li><strong>Endocriniennes</strong> : <strong>hyperthyroïdie</strong>, <strong>insuffisance surrénale aiguë</strong>, <strong>acidocétose diabétique</strong>.</li><li><strong>Neurologiques</strong> : <strong>méningite</strong>, <strong>hémorragie sous-arachnoïdienne</strong>, <strong>HTIC</strong>, <strong>migraine</strong>, <strong>malaise vagal</strong>, <strong>syndrome labyrinthique</strong>.</li><li><strong>Toxiques</strong> : <strong>syndrome cannabinoïde</strong>, <strong>alcool</strong>, <strong>médicaments</strong> (antibiotiques, chimiothérapie, opiacés, néfopam, digitaliques).</li><li><strong>Autres</strong> : <strong>colique néphrétique</strong>, <strong>grossesse</strong> (y compris GEU), <strong>torsion de kyste ovarien</strong>, <strong>IDM</strong>, <strong>glaucome aigu</strong>.</li></ul>"},{"i":"7e7f505298f3","n":274,"o":"274-7","u":"Étiologies","t":"Connaître les causes principales digestives et extradigestives (médicamenteux, métabolique, neurologique, ..)","q":"Quelles sont les principales causes digestives obstructives de vomissements chroniques chez l'adulte ?","a":"<p>Les principales causes digestives obstructives de vomissements chroniques (plus de 7 jours ou récidivants) sont des obstructions mécaniques hautes (gastro-duodéno-grêliques) :</p><ul><li><strong>Tumeurs</strong> : <strong>cancer gastrique</strong>, <strong>duodénal</strong>, <strong>du grêle</strong>, <strong>néoplasies du pancréas</strong>, <strong>carcinose péritonéale</strong>.</li><li><strong>Autres causes mécaniques</strong> : <strong>pseudokyste pancréatique compressif</strong>, <strong>sténose sur ulcère bénin</strong>, <strong>maladie de Crohn</strong>, <strong>sténose post-anastomotique</strong> ou <strong>post-radique</strong>, <strong>sténose sur AINS</strong>.</li></ul>"},{"i":"c214d29ddbb4","n":274,"o":"274-7","u":"Étiologies","t":"Connaître les causes principales digestives et extradigestives (médicamenteux, métabolique, neurologique, ..)","q":"Quelles sont les principales causes digestives non obstructives de vomissements chroniques chez l'adulte ?","a":"<p>Les principales causes digestives non obstructives de vomissements chroniques (plus de 7 jours ou récidivants) incluent :</p><ul><li><strong>Strangulations</strong> : <strong>adhérences</strong>, <strong>brides</strong>, <strong>hernies</strong>.</li><li><strong>Dysfonctionnements fonctionnels</strong> : <strong>gastroparésie</strong> (diabète, sclérodermie, amylose), états <strong>post-vagotomie</strong>, <strong>pseudo-obstruction intestinale</strong> primitive ou secondaire.</li></ul>"},{"i":"ca12ecccf939","n":274,"o":"274-7","u":"Étiologies","t":"Connaître les causes principales digestives et extradigestives (médicamenteux, métabolique, neurologique, ..)","q":"Quelles sont les principales causes digestives de vomissements aigus chez l'adulte ?","a":"<p>Les causes digestives les plus fréquentes de vomissements aigus (moins de 7 jours) chez l'adulte sont :</p><ul><li>La <strong>gastroentérite aiguë virale</strong> et la <strong>toxi-infection alimentaire</strong>.</li><li>La <strong>colique hépatique</strong>.</li><li>La <strong>pancréatite aiguë</strong>.</li><li>Le <strong>syndrome occlusif</strong>.</li><li>L'<strong>infarctus mésentérique</strong>.</li></ul>"},{"i":"5d98fa857c78","n":274,"o":"274-8","u":"Prise en charge","t":"Connaître les principes de prise en charge médicamenteuse (indication, non indication) et non médicamenteuse","q":"Dans quelles situations spécifiques les neuroleptiques antidopaminergiques comme la dompéridone ou le métoclopramide sont-ils contre-indiqués ou doivent-ils être utilisés avec précaution ?","a":"<p>La <strong>dompéridone</strong> est contre-indiquée en cas d'<strong>allongement du QTc</strong>. Le <strong>métoclopramide</strong> est contre-indiqué chez l'<strong>enfant</strong>, en cas de <strong>phéochromocytome</strong>, d'association à la <strong>lévodopa</strong>, de consommation d'alcool, et d'antécédents de <strong>dyskinésie tardive</strong>.</p>"},{"i":"a2cc24cb8d39","n":274,"o":"274-8","u":"Prise en charge","t":"Connaître les principes de prise en charge médicamenteuse (indication, non indication) et non médicamenteuse","q":"Quand les mesures non médicamenteuses sont-elles indiquées pour la prise en charge des vomissements, et quelles sont les principales de ces mesures ?","a":"<p>Les mesures non médicamenteuses sont indiquées pour les vomissements <strong>isolés, bien tolérés et sans retentissement</strong>. Elles incluent :</p><ul><li>Une <strong>alimentation fractionnée, légère, froide, sans odeurs</strong>.</li><li>Des <strong>soins de bouche</strong>.</li><li>Des approches complémentaires comme l'<strong>électrostimulation du nerf vague</strong> ou l'<strong>acupuncture</strong>.</li></ul>"},{"i":"bcffd2216d28","n":274,"o":"274-8","u":"Prise en charge","t":"Connaître les principes de prise en charge médicamenteuse (indication, non indication) et non médicamenteuse","q":"Quelle est la prise en charge antiémétique recommandée et non recommandée des vomissements chez la femme enceinte ?","a":"<p>La prise en charge est d'abord <strong>non médicamenteuse</strong> (éviter les odeurs fortes, alimentation fractionnée, gingembre). Le traitement médicamenteux de référence repose sur la <strong>pyridoxine (vitamine B6)</strong>, seule ou associée à la <strong>doxylamine</strong>, ou les <strong>antihistaminiques H1 (hydroxyzine)</strong>.</p><p>Les antiémétiques classiques comme le <strong>métoclopramide</strong>, la <strong>métopimazine</strong> ou la <strong>dompéridone</strong> sont <strong>peu efficaces et déconseillés en première intention</strong>.</p>"},{"i":"e77baae4115b","n":274,"o":"274-8","u":"Prise en charge","t":"Connaître les principes de prise en charge médicamenteuse (indication, non indication) et non médicamenteuse","q":"Quels sont les neuromédiateurs et les traitements antiémétiques ciblés agissant sur le système vestibulaire en cas de vomissements ?","a":"<p>Le système vestibulaire est impliqué par l'<strong>acétylcholine</strong> et l'<strong>histamine</strong>. Les traitements ciblés sont :</p><ul><li><strong>Anticholinergiques</strong> (ex: <strong>scopolamine</strong>).</li><li><strong>Antihistaminiques</strong> (ex: <strong>diphenhydramine</strong>, <strong>hydroxyzine</strong>).</li></ul>"},{"i":"ec47e6014b74","n":274,"o":"274-8","u":"Prise en charge","t":"Connaître les principes de prise en charge médicamenteuse (indication, non indication) et non médicamenteuse","q":"Quels sont les principaux neuromédiateurs et les traitements antiémétiques ciblés agissant sur la zone chémoréceptrice (CTZ/area postrema) pour contrôler les vomissements ?","a":"<p>La zone chémoréceptrice stimule les vomissements via la <strong>dopamine</strong>, la <strong>sérotonine</strong> et la <strong>substance P</strong>. Les traitements ciblés incluent :</p><ul><li><strong>Antidopaminergiques</strong> (ex: <strong>métoclopramide</strong>, <strong>métopimazine</strong>, <strong>halopéridol</strong>, <strong>chlorpromazine</strong>, <strong>olanzapine</strong>).</li><li><strong>Sétrons</strong> (ex: <strong>ondansétron</strong>) ciblant la sérotonine.</li><li><strong>Aprépitant</strong> (anti-substance P).</li></ul>"}]};